# ─── 브라우저 자동 쿠키 읽기 (macOS 전용) ──────────
def get_cookies_from_browser():
    """Chrome 또는 Safari에서 당근마켓 탭의 쿠키를 자동으로 읽어옴"""
    if platform.system() != "Darwin":
        return ""

    chrome_script = '''
tell application "Google Chrome"
    set found to ""
    repeat with w in windows
        repeat with t in tabs of w
            if URL of t contains "daangn.com" then
                set found to execute javascript "document.cookie" in t
            end if
        end repeat
    end repeat
    return found
end tell'''

    safari_script = '''
tell application "Safari"
    set found to ""
    repeat with w in windows
        if exists (tabs of w) then
            repeat with t in tabs of w
                if URL of t contains "daangn.com" then
                    set found to do JavaScript "document.cookie" in t
                end if
            end repeat
        end if
    end repeat
    return found
end tell'''

    for script in [chrome_script, safari_script]:
        try:
            r = subprocess.run(
                ["osascript", "-e", script],
                capture_output=True, text=True, timeout=6
            )
            ck = r.stdout.strip()
            if ck and len(ck) > 5 and "=" in ck:
                return ck
        except Exception:
            continue
    return ""

